    public LeadService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new LeadEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(LeadRepository.class) );
		this.validator		= applicationContext.getBean(LeadValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Lead
	 */
		public Lead createLead( CreateLeadCommand command ) {

		Lead entity = new Lead();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setLeadId( command.getLeadId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setCompany( command.getCompany() );
            entity.setEmail( command.getEmail() );
            entity.setPhone( command.getPhone() );
            entity.setConverted( command.getConverted() );
            entity.setStatus( command.getStatus() );
            entity.setSource( command.getSource() );
            entity.setRating( command.getRating() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Lead {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateLeadCommand
	 * @return		Lead
	 */
	public Lead updateLead( UpdateLeadCommand command ) {

		Lead entity = new Lead();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setLeadId( command.getLeadId() );
            entity.setFirstName( command.getFirstName() );
            entity.setLastName( command.getLastName() );
            entity.setCompany( command.getCompany() );
            entity.setEmail( command.getEmail() );
            entity.setPhone( command.getPhone() );
            entity.setConverted( command.getConverted() );
            entity.setOrganization( command.getOrganization() );
            entity.setOwner( command.getOwner() );
            entity.setActivities( command.getActivities() );
            entity.setCampaigns( command.getCampaigns() );
            entity.setConvertedAccount( command.getConvertedAccount() );
            entity.setConvertedContact( command.getConvertedContact() );
            entity.setConvertedOpportunity( command.getConvertedOpportunity() );
            entity.setNotes( command.getNotes() );
            entity.setEmailMessages( command.getEmailMessages() );
            entity.setStatus( command.getStatus() );
            entity.setSource( command.getSource() );
            entity.setRating( command.getRating() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Lead {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteLeadCommand
	 */
	public void delete( DeleteLeadCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getLeadId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Lead {0} ", id );

	}

	/**
	 * Method to retrieve the Lead via LeadFetchOneSummary
	 * @param 	summary LeadFetchOneSummary
	 * @return 	LeadFetchOneResponse
	 */
	public Lead getLead( LeadFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "LeadFetchOneSummary arg cannot be null" );

		Lead entity = null;
		UUID id = summary.getLeadId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Lead using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Leads
	 *
	 * @return 	List<Lead>
	 */
    public List<Lead> getAllLead() {
		List<Lead> list = projector.findAll( new FindAllLeadQuery() );
		return list;
	}

